extern "C" int drainage(const float* heights, int h, int w, float nodata,
                        int32_t* downstream, int32_t* area, uint8_t* touches_edge) {
    const int size = h * w;
    const int dy[] = {-1, 0, 1, 0, -1, -1, 1, 1};
    const int dx[] = {0, 1, 0, -1, -1, 1, -1, 1};
    auto neighbor = [&](int i, int k) {
        const int y = i / w + dy[k], x = i % w + dx[k];
        return y >= 0 && y < h && x >= 0 && x < w ? y * w + x : -1;
    };
    std::vector<float> filled(heights, heights + size);
    std::vector<int32_t> order, rank(size, -1);
    order.reserve(size);
    using Node = std::pair<float, int>;
    std::priority_queue<Node, std::vector<Node>, std::greater<Node>> queue;
    std::fill_n(downstream, size, -2);
    std::fill_n(area, size, 0);
    std::fill_n(touches_edge, size, 0);
    for (int i = 0; i < size; ++i) {
