        area[i] = 1;
        for (int k = 0; k < 8; ++k) {
            int j = neighbor(i, k);
            if (j >= 0 && heights[j] != nodata) continue;
            queue.emplace(heights[i], i);
            downstream[i] = -1;
            touches_edge[i] = 1;
            break;
        }
    }
    // Priority-Flood preserves an outlet path to resolve ties across filled depressions.
