            int j = neighbor(i, k);
            if (j < 0 || heights[j] == nodata || downstream[j] != -2) continue;
            filled[j] = std::max(z, heights[j]);
            downstream[j] = i;
            queue.emplace(filled[j], j);
        }
    }
    // On slopes, use the steepest of the eight adjacent directions.
    for (int i : order) {
        float best = 0;
        for (int k = 0; k < 8; ++k) {
            int j = neighbor(i, k);
            if (j < 0 || rank[j] < 0 || rank[j] >= rank[i]) continue;
            float slope = (filled[i] - filled[j]) * (k < 4 ? 1.f : .70710678f);
            if (slope > best) {
                best = slope;
                downstream[i] = j;
            }
        }
    }
    int total = 0;
    for (auto p = order.rbegin(); p != order.rend(); ++p) {
        int i = *p, j = downstream[i];
        if (j < 0) {
            total += area[i];
            continue;
        }
        if (rank[j] >= rank[i]) return -1;
        area[j] += area[i];
        touches_edge[j] |= touches_edge[i];
    }
    return total;
}

